    "apps/web/src/routes/editorial/EditorialArea.tsx" `
    (Decode-Utf8Base64 "aW1wb3J0IHsgVHJhbnNsYXRpb25TdHJ1Y3R1cmVQYWdlIH0gZnJvbSAnLi9UcmFuc2xhdGlvblN0cnVjdHVyZVBhZ2UnOwppbXBvcnQgeyBTb25nQ29udGV4dE5hdmlnYXRpb24gfSBmcm9tICcuL1NvbmdDb250ZXh0TmF2aWdhdGlvbic7Cg==") `
